#include "pc_gvf/paper_guidance.hpp"
#include <cstdlib>
#include <iostream>
#include <sstream>
#include <stdexcept>
using namespace pc_gvf::depth_angular;using V=Eigen::Vector3d;
void check(bool x,const char*m){if(!x){std::cerr<<m<<'\n';std::exit(1);}}
PaperConfig config(){PaperConfig c;c.execution_consistent=c.bounded_exploration=true;c.retain_verified_travel=c.retain_certified_volume=c.certified_direct=c.emergency_braking_certificate=true;c.history_uncertainty_rate=0;c.motion.max_accel=c.motion.brake_accel=16;c.motion.velocity_tau=.1;c.motion.delay=.2;c.motion.rollout_horizon=.2;c.motion.body_radius=.48;c.motion.safety_margin=.02;c.motion.rollout_margin=.02;c.depth_uncertainty=.01;c.uncertainty_rate=.1;c.observation_timeout=.5;c.tracking_margin=.015;c.restart_clearance=.02;c.max_speed=10;c.working_bounds_enabled=true;c.free_space_floor_enabled=c.free_space_ceiling_enabled=true;c.free_space_floor_z=0;c.free_space_ceiling_z=19.8;return c;}
DepthObservation blind(const V& p){Camera cam(24,18,90,74,20);return DepthObservation(cam,std::vector<double>(24*18,0.),p,Eigen::Matrix3d::Identity(),1.);}
int main(){auto c=config();PaperGuidance p(c);check(p.setVerifiedSeed(V(160,0,10),1000.),"seed premise");const auto o=blind(V(160,0,10));const double radius=p.envelopeRadius();check(std::abs(radius-.595)<1e-12,"profile envelope changed");
check(p.envelopeKnown(o,V(160,-59.3,10),radius,1.),"interior body wrongly rejected");check(!p.envelopeKnown(o,V(160,-59.5,10),radius,1.),"giant seed bypassed lower Y body bound");check(!p.envelopeKnown(o,V(399.5,0,10),radius,1.),"upper X body bound omitted");check(!p.envelopeKnown(o,V(-79.5,0,10),radius,1.),"lower X body bound omitted");check(!p.envelopeKnown(o,V(160,59.3,10),radius,1.),"upper Y body bound omitted");
check(p.proposalCorridor(o,V(160,-59,10),-V::UnitY(),.1,1.),"safe short capsule blocked");check(!p.proposalCorridor(o,V(160,-59,10),-V::UnitY(),1.,1.),"capsule bound checked centers only");
p.confirmPublishedCommand(V(0,-3,0));check(!p.motionSafe(o,V(160,-59,10),V(0,-3,0),V::Zero(),1.),"delayed emergency brake escaped working region");check(p.motionSafe(o,V(160,-58.3,10),V(0,-3,0),V::Zero(),1.),"interior delayed brake blocked");
const V recorded(163.8346036733509,-59.98357188539688,13.50869696249889),velocity(-9.52549524047049,-1.7196870487628686,-.5928404341347083),command(-9.86769041651,1.61012148681,-.190248894097);
p.confirmPublishedCommand(command);check(!p.motionSafe(o,recorded,velocity,command,1.),"actual guard pose still nominally certified");auto state=const_cast<ActiveNavigationState*>(&p.activeNavigationState());state->recovering=state->anchor_valid=true;state->anchor=V(164,-57,13.5);check(!p.step(o,recorded,V::Zero(),V::UnitY(),1.,1./60.).accepted,"unknown recovery bypassed working bounds");
auto legacy=c;legacy.working_bounds_enabled=false;PaperGuidance old(legacy);old.setVerifiedSeed(V(160,0,10),100.);old.confirmPublishedCommand(command);check(old.motionSafe(o,recorded,velocity,command,1.),"legacy disabled-domain fixture not valid");
auto narrow=c;narrow.working_min_y=-1;narrow.working_max_y=1;const V at(160,.3,10);auto view=blind(at);PaperGuidance q(narrow);q.setVerifiedSeed(V(160,0,10),100.);std::stringstream stream(std::ios::in|std::ios::out|std::ios::binary);V intent=V::UnitY();q.saveReplay(stream,view,at,V::Zero(),intent,1.,1./60.,&intent);check(stream.str().substr(0,8)=="EGOPAPRV","working domain replay not version V");auto r=q.stepWithProposal(view,at,V::Zero(),intent,intent,1.,1./60.);stream.seekg(0);auto rr=PaperGuidance::replay(stream);check(r.accepted&&r.command.norm()<.99&&r.status==rr.status&&(r.command-rr.command).norm()<1e-12,"V replay lost non-default working region");
bool bad=false;try{auto invalid=c;invalid.working_max_x=invalid.working_min_x;PaperGuidance reject(invalid);}catch(const std::invalid_argument&){bad=true;}check(bad,"invalid domain accepted");std::cout<<"body/capsule/delayed stop/risk domain, actual boundary failure, opt-out and V replay: PASS\n";}
